package com.gukhan.ainlp.security;
import com.gukhan.ainlp.user.UserRepository;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtAuthFilter extends OncePerRequestFilter{private final JwtService jwt;private final UserRepository users;public JwtAuthFilter(JwtService j,UserRepository u){jwt=j;users=u;}
protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){String t=h.substring(7);if(jwt.valid(t)){String n=jwt.username(t);users.findByUsername(n).filter(User::isActive).ifPresent(u->{var a=new UsernamePasswordAuthenticationToken(u.getUsername(),null,java.util.List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole())));SecurityContextHolder.getContext().setAuthentication(a);});}}chain.doFilter(req,res);}}